    try std.testing.expectError(error.MetricStale, db.search(alloc, .{
        .graph_metric_queries = &.{.{
            .name = "hub",
            .query = .{
                .index_name = "graph_idx",
                .metric_name = "hits_hub",
                .top_k = 1,
                .freshness = .fresh,
            },
        }},
        .limit = 0,
