    try std.testing.expectError(error.InvalidArgument, db.preflightSearchRequest(alloc, .{
        .graph_queries = &.{
            .{
                .name = "pattern_missing_type",
                .query = .{
                    .query_type = .pattern,
                    .index_name = "graph_v1",
                    .start_nodes = .{ .keys = &.{"doc:a"} },
                    .pattern = &.{
