test "db relational unique constraints enforce committed scalar values" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .primary_backend = .{ .mem = .{} },
    });
    defer db.close();

    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"tenant_id":{"type":"keyword"},"email":{"type":"keyword"},"handle":{"type":"keyword"},"age":{"type":"numeric"},"slug":{"type":"keyword"},"status":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"unique_constraints":[{"name":"users_email_key","columns":["email"]},{"name":"users_age_key","columns":["age"]},{"name":"users_tenant_handle_key","columns":["tenant_id","handle"]},{"name":"users_active_slug_key","columns":["slug"],"where":{"all":[{"field":"status","op":"eq","value":"active"}]}},{"name":"users_lower_email_key","expressions":[{"op":"lower","field":"email"}]}]}
    ;
    var parsed_schema = try schema_api_mod.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try schema_api_mod.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);
    try db.setSchema(runtime_schema);

    try db.batch(.{
        .writes = &.{
            .{ .key = "user:1", .value = "{\"id\":\"user:1\",\"email\":\"a@example.com\",\"age\":30}" },
            .{ .key = "user:tenant-a", .value = "{\"id\":\"user:tenant-a\",\"tenant_id\":\"tenant:a\",\"handle\":\"sam\"}" },
            .{ .key = "user:tenant-b", .value = "{\"id\":\"user:tenant-b\",\"tenant_id\":\"tenant:b\",\"handle\":\"sam\"}" },
            .{ .key = "user:partial-a", .value = "{\"id\":\"user:partial-a\",\"tenant_id\":\"tenant:a\"}" },
            .{ .key = "user:partial-b", .value = "{\"id\":\"user:partial-b\",\"tenant_id\":\"tenant:a\"}" },
            .{ .key = "user:null-a", .value = "{\"id\":\"user:null-a\"}" },
            .{ .key = "user:null-b", .value = "{\"id\":\"user:null-b\"}" },
            .{ .key = "user:inactive-a", .value = "{\"id\":\"user:inactive-a\",\"slug\":\"sam\",\"status\":\"inactive\"}" },
            .{ .key = "user:inactive-b", .value = "{\"id\":\"user:inactive-b\",\"slug\":\"sam\",\"status\":\"inactive\"}" },
            .{ .key = "user:active-a", .value = "{\"id\":\"user:active-a\",\"slug\":\"sam\",\"status\":\"active\"}" },
        },
    });

    try std.testing.expectError(error.UniqueConstraintViolation, db.batch(.{
        .writes = &.{.{ .key = "user:2", .value = "{\"id\":\"user:2\",\"email\":\"a@example.com\",\"age\":31}" }},
    }));
    try std.testing.expectError(error.UniqueConstraintViolation, db.batch(.{
        .writes = &.{.{ .key = "user:2-case", .value = "{\"id\":\"user:2-case\",\"email\":\"A@EXAMPLE.COM\",\"age\":41}" }},
    }));
    try std.testing.expectError(error.UniqueConstraintViolation, db.batch(.{
        .writes = &.{.{ .key = "user:3", .value = "{\"id\":\"user:3\",\"email\":\"b@example.com\",\"age\":30}" }},
    }));
    try std.testing.expectError(error.UniqueConstraintViolation, db.batch(.{
        .writes = &.{.{ .key = "user:tenant-a-dup", .value = "{\"id\":\"user:tenant-a-dup\",\"tenant_id\":\"tenant:a\",\"handle\":\"sam\"}" }},
    }));
    try std.testing.expectError(error.UniqueConstraintViolation, db.batch(.{
        .writes = &.{.{ .key = "user:active-b", .value = "{\"id\":\"user:active-b\",\"slug\":\"sam\",\"status\":\"active\"}" }},
    }));

    try db.batch(.{
        .writes = &.{.{ .key = "user:1", .value = "{\"id\":\"user:1\",\"email\":\"b@example.com\",\"age\":32}" }},
    });
    try db.batch(.{
        .writes = &.{.{ .key = "user:2", .value = "{\"id\":\"user:2\",\"email\":\"a@example.com\",\"age\":30}" }},
    });

    try db.batch(.{
        .deletes = &.{"user:2"},
    });
    const deleted_user_2_row = try relational_store_mod.getRawAlloc(alloc, db.core.store, "user:2");
    defer if (deleted_user_2_row) |row| alloc.free(row);
    try std.testing.expect(deleted_user_2_row == null);
    const reusable_email_value = try testUniqueTupleValueAlloc(alloc, &.{"a@example.com"});
    defer alloc.free(reusable_email_value);
    const reusable_email_key = try internal_keys.relationalUniqueKeyAlloc(alloc, "users_email_key", reusable_email_value);
    defer alloc.free(reusable_email_key);
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, reusable_email_key));
    try db.batch(.{
        .writes = &.{.{ .key = "user:3", .value = "{\"id\":\"user:3\",\"email\":\"a@example.com\",\"age\":30}" }},
    });
    try db.batch(.{
        .writes = &.{.{ .key = "user:tenant-a", .value = "{\"id\":\"user:tenant-a\",\"tenant_id\":\"tenant:a\",\"handle\":\"alex\"}" }},
    });
    try db.batch(.{
        .writes = &.{.{ .key = "user:tenant-a-dup", .value = "{\"id\":\"user:tenant-a-dup\",\"tenant_id\":\"tenant:a\",\"handle\":\"sam\"}" }},
    });
    try db.batch(.{
        .deletes = &.{"user:tenant-a-dup"},
    });
    try db.batch(.{
        .writes = &.{.{ .key = "user:tenant-a-reuse", .value = "{\"id\":\"user:tenant-a-reuse\",\"tenant_id\":\"tenant:a\",\"handle\":\"sam\"}" }},
    });
    try db.batch(.{
        .writes = &.{.{ .key = "user:active-a", .value = "{\"id\":\"user:active-a\",\"slug\":\"sam\",\"status\":\"inactive\"}" }},
    });
    try db.batch(.{
        .writes = &.{.{ .key = "user:active-b", .value = "{\"id\":\"user:active-b\",\"slug\":\"sam\",\"status\":\"active\"}" }},
    });

    const txn_id = try db.beginTransaction(20_000);
    try db.writeIntents(txn_id, &.{
        .{ .key = "user:txn", .value = "{\"id\":\"user:txn\",\"email\":\"a@example.com\",\"age\":40}" },
    }, &.{});
    try std.testing.expectError(error.UniqueConstraintViolation, db.commitTransaction(txn_id, 20_001));
    try db.abortTransaction(txn_id, 20_002);
}

test "db relational composite primary keys enforce identity and back foreign keys" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .primary_backend = .{ .mem = .{} },
    });
    defer db.close();

    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"tenant_id":{"type":"keyword"},"order_id":{"type":"keyword"},"parent_order_id":{"type":"keyword"},"status":{"type":"keyword"}},"required":["tenant_id","order_id"],"additionalProperties":false}}},"primary_key":{"columns":["tenant_id","order_id"]},"foreign_keys":[{"name":"orders_parent_fkey","columns":["tenant_id","parent_order_id"],"references":{"table":"row","columns":["tenant_id","order_id"]},"on_delete":"restrict","on_update":"restrict","match":"full"}]}
    ;
    var parsed_schema = try schema_api_mod.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try schema_api_mod.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);
    try db.setSchema(runtime_schema);

    try db.batch(.{
        .writes = &.{
            .{ .key = "order:parent", .value = "{\"tenant_id\":\"tenant:a\",\"order_id\":\"parent\",\"status\":\"open\"}" },
            .{ .key = "order:child", .value = "{\"tenant_id\":\"tenant:a\",\"order_id\":\"child\",\"parent_order_id\":\"parent\",\"status\":\"open\"}" },
        },
    });

    const parent_row_key = try internal_keys.relationalRowKeyAlloc(alloc, "order:parent");
    defer alloc.free(parent_row_key);
    const parent_row = try db.core.store.get(alloc, parent_row_key);
    defer alloc.free(parent_row);
    const parent_tuple = try relational_store_mod.primaryKeyTupleValueAlloc(alloc, parent_row, runtime_schema.primary_key.?);
    defer alloc.free(parent_tuple);
    const parent_owner_key = try internal_keys.relationalUniqueKeyAlloc(alloc, relational_store_mod.primary_key_constraint_name, parent_tuple);
    defer alloc.free(parent_owner_key);
    const parent_owner = try db.core.store.get(alloc, parent_owner_key);
    defer alloc.free(parent_owner);
    try std.testing.expectEqualStrings("order:parent", parent_owner);

    try db.core.store.delete(parent_owner_key);
    const missing_owner_report = try db.validateUniqueConstraintRowsInRange("", "");
    try std.testing.expect(!missing_owner_report.valid());
    try std.testing.expectEqual(@as(u64, 1), missing_owner_report.missing_unique_rows);
    const repair_owner_report = try db.repairUniqueConstraintRowsInRange("", "");
    try std.testing.expectEqual(@as(u64, 1), repair_owner_report.repaired_unique_rows);
    const validate_repaired_owner_report = try db.validateUniqueConstraintRowsInRange("", "");
    try std.testing.expect(validate_repaired_owner_report.valid());
    const repaired_parent_owner = try db.core.store.get(alloc, parent_owner_key);
    defer alloc.free(repaired_parent_owner);
    try std.testing.expectEqualStrings("order:parent", repaired_parent_owner);

    try std.testing.expectError(error.UniqueConstraintViolation, db.batch(.{
        .writes = &.{.{ .key = "order:duplicate", .value = "{\"tenant_id\":\"tenant:a\",\"order_id\":\"parent\",\"status\":\"duplicate\"}" }},
    }));
    try std.testing.expectError(error.InvalidBatchRequest, db.batch(.{
        .writes = &.{.{ .key = "order:missing-key", .value = "{\"tenant_id\":\"tenant:a\",\"status\":\"missing\"}" }},
    }));
    try std.testing.expectError(error.ForeignKeyViolation, db.batch(.{
        .writes = &.{.{ .key = "order:missing-parent", .value = "{\"tenant_id\":\"tenant:a\",\"order_id\":\"missing-parent\",\"parent_order_id\":\"absent\"}" }},
    }));
    try std.testing.expectError(error.ForeignKeyViolation, db.batch(.{
        .deletes = &.{"order:parent"},
    }));
    try std.testing.expectError(error.ForeignKeyViolation, db.batch(.{
        .writes = &.{.{ .key = "order:parent", .value = "{\"tenant_id\":\"tenant:a\",\"order_id\":\"parent-renamed\",\"status\":\"renamed\"}" }},
    }));

    const report = try db.validateForeignKeyRefsInRange("", "");
    try std.testing.expect(report.valid());
}

test "db system-versioned relational tables capture durable row history" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .primary_backend = .{ .mem = .{} },
    });
    defer db.close();

    const base_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"name":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var base_parsed_schema = try schema_api_mod.parseValidatedTableSchema(alloc, base_schema_json);
    defer base_parsed_schema.deinit(alloc);
    const base_runtime_schema = try schema_api_mod.deriveRuntimeTableSchema(alloc, base_parsed_schema);
    defer schema_mod.freeSchema(alloc, base_runtime_schema);
    try db.setSchema(base_runtime_schema);

    try db.batch(.{
        .writes = &.{.{ .key = "row:1", .value = "{\"id\":\"row:1\",\"name\":\"before\"}" }},
    });

    const versioned_schema_json =
        \\{"version":2,"storage_mode":"relational","default_type":"row","enforce_types":true,"system_versioned":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"name":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var versioned_parsed_schema = try schema_api_mod.parseValidatedTableSchema(alloc, versioned_schema_json);
    defer versioned_parsed_schema.deinit(alloc);
    const versioned_runtime_schema = try schema_api_mod.deriveRuntimeTableSchema(alloc, versioned_parsed_schema);
    defer schema_mod.freeSchema(alloc, versioned_runtime_schema);
    try std.testing.expect(versioned_runtime_schema.system_versioned);
    try db.setSchema(versioned_runtime_schema);

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:1", .value = "{\"id\":\"row:1\",\"name\":\"batch\"}" },
            .{ .key = "row:2", .value = "{\"id\":\"row:2\",\"name\":\"inserted\"}" },
        },
    });
    try db.batch(.{
        .deletes = &.{"row:2"},
    });

    const row_1_history = try db.scanSystemVersionedHistoryForDocKeyAlloc(alloc, "row:1");
    defer docstore_mod.DocStore.freeResults(alloc, row_1_history);
    try std.testing.expectEqual(@as(usize, 1), row_1_history.len);
    try std.testing.expect(std.mem.indexOf(u8, row_1_history[0].value, "\"operation\":\"update\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, row_1_history[0].value, "before") != null);
    try std.testing.expect(std.mem.indexOf(u8, row_1_history[0].value, "batch") != null);

    const row_2_history = try db.scanSystemVersionedHistoryForDocKeyAlloc(alloc, "row:2");
    defer docstore_mod.DocStore.freeResults(alloc, row_2_history);
    try std.testing.expectEqual(@as(usize, 2), row_2_history.len);
    try std.testing.expect(std.mem.indexOf(u8, row_2_history[0].value, "\"operation\":\"insert\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, row_2_history[1].value, "\"operation\":\"delete\"") != null);

    const row_2_insert_sequence = try systemVersionedHistoryRecordCommitSequence(row_2_history[0].value);
    const row_2_delete_sequence = try systemVersionedHistoryRecordCommitSequence(row_2_history[1].value);
    const row_2_predicates = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "id",
        .op = .eq,
        .value_json = "\"row:2\"",
    }};
    var row_2_as_of_insert = try db.querySystemVersionedRelationalRowsAsOfSequence(alloc, versioned_runtime_schema, row_2_insert_sequence, .{
        .predicates = row_2_predicates[0..],
        .select_all = true,
    });
    defer row_2_as_of_insert.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), row_2_as_of_insert.total);
    try std.testing.expect(std.mem.indexOf(u8, row_2_as_of_insert.rows[0], "inserted") != null);
    var row_2_as_of_delete = try db.querySystemVersionedRelationalRowsAsOfSequence(alloc, versioned_runtime_schema, row_2_delete_sequence, .{
        .predicates = row_2_predicates[0..],
        .select_all = true,
    });
    defer row_2_as_of_delete.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 0), row_2_as_of_delete.total);

    const txn_id = try db.beginTransaction(20_000);
    try db.writeTransaction(txn_id, .{
        .writes = &.{.{ .key = "row:1", .value = "{\"id\":\"row:1\",\"name\":\"txn\"}" }},
    });
    try db.commitTransaction(txn_id, 20_001);

    const mutation_txn_id = try db.beginTransaction(30_000);
    const predicates = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "id",
        .op = .eq,
        .value_json = "\"row:1\"",
    }};
    const operations = [_]types.TransformOp{.{
        .op = .set,
        .path = "name",
        .value_json = "\"after\"",
    }};
    var mutation_result = try db.mutateRelationalRowsFromSource(alloc, versioned_runtime_schema, .{
        .kind = .update,
        .source = .{
            .predicates = predicates[0..],
            .row_claim = .{
                .mode = .for_update,
                .owner_id = "session:system-versioned",
                .txn_id = mutation_txn_id,
            },
        },
        .operations = operations[0..],
    });
    defer mutation_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), mutation_result.staged);
    try db.commitTransaction(mutation_txn_id, 30_001);

    const current = (try db.get(alloc, "row:1")) orelse return error.TestExpectedEqual;
    defer alloc.free(current);
    try std.testing.expect(std.mem.indexOf(u8, current, "\"after\"") != null);

    const row_1_final_history = try db.scanSystemVersionedHistoryForDocKeyAlloc(alloc, "row:1");
    defer docstore_mod.DocStore.freeResults(alloc, row_1_final_history);
    try std.testing.expectEqual(@as(usize, 3), row_1_final_history.len);
    try std.testing.expect(std.mem.indexOf(u8, row_1_final_history[1].value, "txn") != null);
    try std.testing.expect(std.mem.indexOf(u8, row_1_final_history[2].value, "after") != null);
    const row_1_txn_sequence = try systemVersionedHistoryRecordCommitSequence(row_1_final_history[1].value);
    const row_1_predicates = [_]schema_mod.RelationalCheck{.{
        .name = "",
        .field = "id",
        .op = .eq,
        .value_json = "\"row:1\"",
    }};
    var row_1_as_of_txn = try db.querySystemVersionedRelationalRowsAsOfSequence(alloc, versioned_runtime_schema, row_1_txn_sequence, .{
        .predicates = row_1_predicates[0..],
        .select_all = true,
    });
    defer row_1_as_of_txn.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), row_1_as_of_txn.total);
    try std.testing.expect(std.mem.indexOf(u8, row_1_as_of_txn.rows[0], "txn") != null);
    try std.testing.expect(std.mem.indexOf(u8, row_1_as_of_txn.rows[0], "after") == null);
    try std.testing.expectError(error.UnsupportedQueryRequest, db.querySystemVersionedRelationalRowsAsOfSequence(alloc, base_runtime_schema, row_1_txn_sequence, .{}));
}

