    try std.testing.expectEqualStrings("{\"tenant\":\"t2\",\"id\":\"e\",\"amount\":5,\"expr_range_count\":1}", expression_range.rows[4]);

    const source_scoped_window_amount = types.RelationalRowsExpression{
        .kind = .field,
        .field = "amount",
